-- Hub Giulia 3.9 — a completed procedure must not keep the same appointment as the patient's next action.
create or replace function public.get_patient_next_action_v1(p_patient_id uuid,p_appointment_id uuid default null) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
with allowed_patient as(select p.id from public.patients p where p.id=p_patient_id and p.user_id=auth.uid() limit 1),today_appointment as(select 1000 rank,a.scheduled_at due_at,'appointment_today'::text source_type,a.id source_id,case when a.status='confirmado' then 'Atendimento hoje' else 'Atendimento hoje aguardando confirmação' end title,case when a.status='confirmado' then 'Iniciar atendimento' else 'Confirmar horário' end action_label,case when a.status='confirmado' then 'start_attendance' else 'open_communication' end action_type,case when a.status='confirmado' then '/atendimento/'||a.id::text else '/comunicacao?category=confirmation' end route from public.appointments a join allowed_patient p on p.id=a.patient_id where a.user_id=auth.uid() and a.status in('pendente','confirmado') and(a.scheduled_at at time zone 'America/Sao_Paulo')::date=(now() at time zone 'America/Sao_Paulo')::date and(p_appointment_id is null or a.id=p_appointment_id) and not exists(select 1 from public.procedures pr where pr.user_id=a.user_id and pr.appointment_id=a.id) order by case when a.id=p_appointment_id then 0 else 1 end,a.scheduled_at limit 1),attention_action as(select a.priority_rank rank,a.due_at,a.source_type,a.source_id,a.title,a.action_label,a.action_type,a.action_route route from public.operational_attention_v1 a join allowed_patient p on p.id=a.patient_id order by a.priority_rank desc,a.due_at asc nulls last limit 1),future_appointment as(select 250 rank,a.scheduled_at due_at,'appointment'::text source_type,a.id source_id,'Próximo atendimento' title,'Ver agendamento' action_label,'open_appointment' action_type,'/agenda?date='||to_char(a.scheduled_at at time zone 'America/Sao_Paulo','YYYY-MM-DD') route from public.appointments a join allowed_patient p on p.id=a.patient_id where a.user_id=auth.uid() and a.status in('pendente','confirmado') and a.scheduled_at>now() and not exists(select 1 from public.procedures pr where pr.user_id=a.user_id and pr.appointment_id=a.id) order by a.scheduled_at limit 1),candidates as(select * from today_appointment union all select * from attention_action union all select * from future_appointment),chosen as(select * from candidates order by rank desc,due_at asc nulls last limit 1) select case when not exists(select 1 from allowed_patient) or not exists(select 1 from chosen) then null else(select jsonb_build_object('source_type',c.source_type,'source_id',c.source_id,'title',c.title,'due_at',c.due_at,'action_type',c.action_type,'action_label',c.action_label,'route',c.route,'priority_rank',c.rank) from chosen c) end; $$;
revoke all on function public.get_patient_next_action_v1(uuid,uuid) from public,anon;
grant execute on function public.get_patient_next_action_v1(uuid,uuid) to authenticated;
